  id: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  exports: any;
  parent?: Module;
  filename: string;
  loaded: boolean;
  children: Module[];
  paths: string[];
  path: string;
  constructor(id = "", parent?: Module) {
    this.id = id;
    this.exports = {};
    this.parent = parent;
    updateChildren(parent, this, false);
    this.filename = null;
    this.loaded = false;
    this.children = [];
    this.paths = [];
    this.path = path.dirname(id);
